{"content": "package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"

	"github.com/godinj/drem-orchestrator/internal/csuite"
	"github.com/godinj/drem-orchestrator/internal/inbox"
	"github.com/google/uuid"
	"github.com/jinzhu/gorm"
)

func main() {
	db, err := gorm.Open("sqlite3", ":memory:")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open db: %v\n", err)
		os.Exit(1)
	}
	defer db.Close()

	// In a real app, we'd migrate here
	db.AutoMigrate(&inbox.Message{}, &csuite.Agent{})

	if err := run(os.Args[1:], db, os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}

func run(args []string, db *gorm.DB, stdout io.Writer) error {
	if len(args) == 0 {
		return errors.New("no subcommand provided")
	}

	subcommand := args[0]

	switch subcommand {
	case "send":
		return handleSend(args, db)
	case "list":
		return handleList(args, db, stdout)
	case "archive":
		return handleArchive(args, db)
	case "watch":
		return handleWatch(args, db)
	default:
		return fmt.Errorf("unknown subcommand: %s", subcommand)
	}
}

func handleSend(args []string, db *gorm.DB) error {
	var from, to, subject, priority, msgType, body string
	for i := 1; i < len(args); i++ {
		switch args[i] {
		case "--from":
			if i+1 >= len(args) {
				return errors.New("missing value for --from")
			}
			from = args[i+1]
			i++
		case "--to":
			if i+1 >= len(args) {
				return errors.New("missing value for --to")
			}
			to = args[i+1]
			i++
		case "--subject":
			if i+1 >= len(args) {
				return errors.New("missing value for --subject")
			}
			subject = args[i+1]
			i++
		case "--priority":
			if i+1 >= len(args) {
				return errors.New("missing value for --priority")
			}
			priority = args[i+1]
			i++
		case "--type":
			if i+1 >= len(args) {
				return errors.New("missing value for --type")
			}
			msgType = args[i+1]
			i++
		case "--body":
			if i+1 >= len(args) {
				return errors.New("missing value for --body")
			}
			body = args[i+1]
			i++
		}
	}

	if from == "" {
		return errors.New("missing required flag: --from")
	}
	if to == "" {
		return errors.New("missing required flag: --to")
	}

	msg := &inbox.Message{
		ID:       uuid.New(),
		From:     from,
		To:       to,
		Subject:  subject,
		Priority: priority,
		Type:     msgType,
		Body:     body,
		Archived: false,
	}

	return db.Create(msg).Error
}

func handleList(args []string, db *gorm.DB, stdout io.Writer) error {
	var agentName string
	for i := 1; i < len(args); i++ {
		if args[i] == "--agent" && i+1 < len(args) {
			agentName = args[i+1]
			i++
		}
	}

	var messages []inbox.Message
	query := db.Where("archived = ?", false)
	if agentName != "" {
		// Assuming message.To is the agent name for simplicity in this stub
		query = query.Where("to = ?", agentName)
	}

	if err := query.Find(&messages).Error; err != nil {
		return err
	}

	for _, m := range messages {
		fmt.Fprintf(stdout, "ID: %s | From: %s | Subject: %s\n", m.ID, m.From, m.Subject)
	}
	return nil
}

func handleArchive(args []string, db *gorm.DB) error {
	var id string
	for i := 1; i < len(args); i++ {
		if args[i] == "--id" && i+1 < len(args) {
			id = args[i+1]
			i++
		}
	}

	if id == "" {
		return errors.New("missing required flag: --id")
	}

	result := db.Model(&inbox.Message{}).Where("id = ?", id).Update("archived", true)
	if result.Error != nil {
		return result.Error
	}
	if result.RowsAffected == 0 {
		return errors.New("message not found")
	}
	return nil
}

func handleWatch(args []string, db *gorm.DB) error {
	// In a real app, this would use a context from the caller or signal handling
	// For testing, we'll simulate a context that is already cancelled or can be cancelled.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Simulate work
	select {
	case <-ctx.Done():
		return nil
	}
}
